/**
 * da.js — the Danish dictionary.
 *
 * Moved out of hooks/useLanguage.jsx (Sep 2026) so each visitor downloads
 * only the language they use: English and Danish were ~850 KB inline in the
 * provider, the largest thing on every first visit. Loaded on demand by
 * i18n/localeStore.js, exactly like the other language packs.
 *
 * Rules (enforced by the i18n guards in scripts/ and src/__tests__/):
 *   • every key exists in BOTH en.js and da.js, with real text in each;
 *   • DK terms stay Danish in every language (MOMS, SKAT, kasserapport,
 *     kreditnota, faktura, lønseddel, revisor, gavekort …);
 *   • one entry per line where possible, 4-space indent — the guards read
 *     this file as text.
 */
