    mileageStep2Body: "Første 20.000 km/år: 3,79 kr/km. Over 20.000 km: 2,23 kr/km. Vi fryser satsen på hver post, så selv hvis Skattestyrelsen ændrer satser næste år, forbliver dine gamle poster korrekte.",
    mileageStep3Title: "3. Hold øje med YTD-kortet",
    mileageStep3Body: "Topkortet viser total km logget i år, dit fradragsberettigede beløb i kroner, og hvilken sats du er i lige nu. De fleste ejere misser 10-15.000 kr/år ved ikke at spore — dette kort gør det konkret.",
    mileageStep4Title: "4. Gem dine brændstofkvitteringer separat",
    mileageStep4Body: "Kørselsgodtgørelse erstatter faktiske brændstof/vedligehold-omkostninger — du kan ikke kræve begge. Behold kvitteringer som dokumentation, men fradraget beregnes fra km-loggen, ikke fra kvitteringerne.",
    mileageHowFooter: "Sats jf. Skattestyrelsens befordringsgodtgørelse 2026. Loggen skal være ført løbende (Bogføringsloven §11) — den kan kræves dokumenteret ved kontrol.",
