    landingFeaturesTag: "Hvad ændrer sig fra mandag morgen",
    landingFeaturesTitle: "Seks ting der gør livet nemmere.",
    landingFeaturesSub: "BonBox er ikke \"endnu et bogføringsprogram.\" Det er laget der laver 12 panik-øjeblikke om ugen — lukning, MOMS, faktura-jagt, revisor-mail, weekendvagter — om til én rolig rytme.",
    landingFeatBriefTitle: "Åbn appen kl. 8 og vid allerede hvad du skal gøre.",
    landingFeatBriefBody: "Morgenbrief kl. 8 lander med gårsdagens omsætning, MOMS-nedtælling, ubetalte fakturaer, faste kunder der glider væk, faste regninger der forfalder. Ét tryk på hver indsigt løser den. Du genfinder morgenrytmen.",
    landingFeatHeroTitle: "Luk kassen på 30 sekunder. Gå hjem.",
    landingFeatHeroBody: "Tag billede af Z-rapporten, BonBox læser tallene. Fire tryk — omsætning, betalinger, kontant, gennemgå. Kasserapporten er signeret, låst og klar til SKAT. Sparer de 20 minutters indtastning du laver hver aften.",
    landingFeatFakturaTitle: "Få betaling hurtigere. Jagt mindre.",
    landingFeatFakturaBody: "Send fakturaer med ét klik — gap-frit fakturanummer efter bogføringsloven. Bankindbetalinger matches automatisk til åbne fakturaer ved næste CSV-upload. Forsinkede dukker op i morgenbriefen før de bliver til et telefonopkald.",
    landingFeatBankTitle: "Stop med at taste kvitteringer ind i Excel.",
    landingFeatBankBody: "Tag billede af en kvittering med din telefon — kvitterings-OCR udfylder bilaget på 4 sekunder. Upload din netbank-CSV — BonBox matcher indgående betalinger til åbne fakturaer med konfidens-niveauer. Excel-arket din bogholder hader? Væk.",
    landingFeatStaffTitle: "Stop med at gætte på weekend-bemanding.",
    landingFeatStaffBody: "Vagtplan-autopilot læser vejrudsigt, dine seneste 8 ugers omsætning og 11-timersreglen — foreslår næste uge med ét tryk. Juster pr. vagt, publicer.",
    landingFeatRevisorTitle: "Din revisor stopper med at ringe.",
    landingFeatRevisorBody: "Inviter din bogholder med en email — de får et læs-kun login, alle handlinger audit-logges. Ingen delte passwords, ingen GDPR-risiko, ingen månedlig \"send mig CSVerne\" mail. SAF-T + kasserapport + faktura, klar når de har brug for det.",
    // Task #171 — fokuseret capabilities-showcase (EN/DA-paritet).  9 kerne-
