    landingCapTitle: "Få ting — gjort ordentligt.",
    landingCapSub: "Ikke 30 halvfærdige funktioner der kæmper om din opmærksomhed. Kernen i at drive en dansk småvirksomhed — lukning, MOMS, faktura, vagtplan, din revisor — hver enkelt bygget til at bære sin vægt.",
