    landingCatMoney1: "Salgssporing · Z-rapport-foto",
    landingFreeF1: "Salg + udgifter + daglig lukning",
    landingFaq6A: "Du falder automatisk ned til Free — intet kort, ingen auto-træk. Free beholder salg + udgifter + daglig lukning + AI-brief for altid. For at få faktura + bank-match + brand-PDF, opgrader til Starter 199 kr./md (129 kr. som stifter) eller Pro 349 kr./md (249 kr. som stifter), pr. virksomhed, der lægges ikke moms oven i — eller bliv på Free. Prisen står på denne side; intet skjules.",
    landingFeature1Title: "Salg & pengestrøm", landingFeature1Desc: "Log salg med 2 tryk. Se omsætning, overskud og pengestrøm — synkroniseret med din kassebog i realtid.",
    landingFeature2Title: "Lager & beholdning", landingFeature2Desc: "Følg lagerniveauer, få advarsler om lav beholdning, sælg varer med automatisk lagertræk. Skabeloner til 21+ virksomhedstyper.",
    landingFeature3Title: "Bar udskænkning", landingFeature3Desc: "Køb flasker i bulk, sælg pr. glas. Auto-registrer udskænkning, træk fra lager og log salg pr. drink.",
    landingFeature4Title: "Smart bemanding", landingFeature4Desc: "AI-drevne vagter baseret på dine travleste dage + vejrudsigt. De rigtige folk på det rigtige tidspunkt.",
    landingFeature5Title: "Forretningssundhed", landingFeature5Desc: "Få en score fra 0-100. Rentabilitet, konsistens, omkostningsstyring — med ét blik.",
    landingFeature6Title: "Spildregistrering", landingFeature6Desc: "Log udløbet og spildt lager. Se hvor meget du taber. Reducer spild, øg overskud.",
    landingFeature7Title: "Vejr Smart", landingFeature7Desc: "Regn = mindre trafik. Se hvordan vejret påvirker din omsætning og planlæg bemanding smartere.",
    landingFeature8Title: "Værkstedsstyring", landingFeature8Desc: "Jobkort, køretøjssporing, reservedele og arbejdsafregning, mekanikeroversigt — bygget til autoværksteder.",
    landingFeature9Title: "Multi-Forretning", landingFeature9Desc: "Kør en café og et værksted under ét login. Hver filial får sin egen type, navigation og daglig lukning.",
    landingFeature10Title: "Vinkort", landingFeature10Desc: "Scan flasker med AI, opret dit vinkort, generér QR-menuer til gæster og få sommelier-råd.",
